update public.learning_paths
set
  title = 'Form and Analysis',
  goal = 'Form and Analysis',
  summary = 'This course develops advanced skills in analyzing musical structure across phrase, theme, movement, and multi-movement levels. Students study motives, phrases, periods, cadences, binary and ternary forms, variations, rondos, sonata and concerto forms, fugue, large-scale cycles, 20th-century and contemporary forms, and analytical writing. The course emphasizes score study, listening, formal diagrams, historical style, evidence-based interpretation, and clear written argument.',
  data = $fanajson${"slug": "form-and-analysis", "title": "Form and Analysis", "description": "This course develops advanced skills in analyzing musical structure across phrase, theme, movement, and multi-movement levels. Students study motives, phrases, periods, cadences, binary and ternary forms, variations, rondos, sonata and concerto forms, fugue, large-scale cycles, 20th-century and contemporary forms, and analytical writing. The course emphasizes score study, listening, formal diagrams, historical style, evidence-based interpretation, and clear written argument.", "topics": [{"id": "b96a8f0f-93d5-43a0-9f13-2aa560c96ad7", "type": "topic", "title": "Motive, Phrase, and Period", "description": "Form begins at the smallest meaningful units. Students learn how motives generate phrases, how phrases create expectation, and how periods and sentences shape local musical logic.", "children": [{"id": "f90b921b-e857-41ca-a422-f5919cbc267e", "type": "subtopic", "title": "Motivic identity and transformation", "children": [{"id": "15965b88-0483-415d-8e5b-7a56cfe9ff07", "type": "concept", "title": "Intervallic profile"}, {"id": "165f69a0-3546-4f57-be57-51d8d6ef5a29", "type": "concept", "title": "Rhythmic profile"}, {"id": "04b0a793-1459-4c27-b9c0-93aa491e7176", "type": "concept", "title": "Sequence"}, {"id": "9f4b58b4-d16d-4543-9c88-7e09a7353989", "type": "concept", "title": "Fragmentation"}, {"id": "b5827e21-072f-414a-a722-c0959ddaa80f", "type": "concept", "title": "Expansion and compression"}], "description": "Why learn it: Students learn to hear and mark the small cells that unify a passage and drive development."}, {"id": "e56f177c-64f9-4b35-a743-dca547797969", "type": "subtopic", "title": "Phrase structure", "children": [{"id": "981e6ee2-3469-453a-9da7-6a93dd3e0f39", "type": "concept", "title": "Basic idea"}, {"id": "4e236051-af48-468a-ad7d-fcde70d49533", "type": "concept", "title": "Cadential idea"}, {"id": "c7f85ea6-b0b0-43ca-b09c-0a5cac65cfbd", "type": "concept", "title": "Phrase rhythm"}, {"id": "44100cce-16e7-4541-ac99-7cf3c28f1abd", "type": "concept", "title": "Expansion"}, {"id": "3b132582-d5e0-49b6-a966-1fa80da5c6b8", "type": "concept", "title": "Elision"}], "description": "Why learn it: Students identify phrase beginnings, endings, cadences, and extensions."}, {"id": "064a8ef5-7413-4f20-94b3-e8b436cf47cd", "type": "subtopic", "title": "Periods and sentences", "children": [{"id": "454174d2-408c-41ae-bb66-10f346258989", "type": "concept", "title": "Antecedent and consequent"}, {"id": "3c0aca11-b10e-4df6-b0df-5449c2e33cd6", "type": "concept", "title": "Presentation"}, {"id": "e0821099-90b2-4cb7-86b4-668de5a47478", "type": "concept", "title": "Continuation"}, {"id": "fca32b05-4567-42ee-b267-19d9cb49092e", "type": "concept", "title": "Cadential function"}, {"id": "8d80e40b-a4d7-42e5-8e1a-1f2357f4fc5a", "type": "concept", "title": "Hybrid themes"}], "description": "Why learn it: Students learn two foundational theme types and how composers modify them."}]}, {"id": "4f550e64-ed57-4921-bf31-f5722874b179", "type": "topic", "title": "Cadences, Harmonic Function, and Formal Syntax", "description": "This added topic strengthens the bridge between harmony and form. Students learn how cadences, prolongation, modulation, and harmonic rhythm create formal boundaries and large-scale direction.", "children": [{"id": "1acb2045-bce6-47fe-8a26-64ef01c7ba16", "type": "subtopic", "title": "Cadential types and strength", "children": [{"id": "94f03330-fff4-43f1-96ad-047c051e69d2", "type": "concept", "title": "Authentic cadences"}, {"id": "428b940c-4140-4b79-b13a-ab4d725c0e57", "type": "concept", "title": "Half cadences"}, {"id": "9a08ae3e-f7aa-4c0a-ba22-0cc729c7de1f", "type": "concept", "title": "Deceptive motion"}, {"id": "08a0b9f4-b8b4-425a-b331-81423bf1d988", "type": "concept", "title": "Evaded cadences"}, {"id": "f4dc02a3-13ee-41c7-a13d-e548a3922210", "type": "concept", "title": "Cadential expansion"}], "description": "Why learn it: Students learn how cadences confirm, defer, weaken, or redirect formal closure."}, {"id": "eeea4ecd-a1e4-4173-9d1c-3c3f719329de", "type": "subtopic", "title": "Harmonic rhythm and phrase rhythm", "children": [{"id": "123398a5-93d1-4c40-bf1b-c2cd9a191463", "type": "concept", "title": "Acceleration"}, {"id": "36e780c5-ec58-440c-9ad7-c61b16ba3669", "type": "concept", "title": "Deceleration"}, {"id": "06194cec-f4a9-42bd-a158-33db10c15281", "type": "concept", "title": "Pedal points"}, {"id": "ab29e8cf-e157-4592-89e2-6066a6dc28a2", "type": "concept", "title": "Sequential motion"}, {"id": "2e9b8e10-1772-45fb-926f-2d3854bd4183", "type": "concept", "title": "Phrase overlap"}], "description": "Why learn it: Students connect the speed of harmonic change to phrase shape and formal arrival."}, {"id": "96ef93fb-2f11-4c2a-9660-fb432f255192", "type": "subtopic", "title": "Formal function", "children": [{"id": "fd1b916a-f252-4057-a937-ff4bd2726694", "type": "concept", "title": "Initiation"}, {"id": "64c2fe35-ec07-4e86-b0ae-98c9f6663e06", "type": "concept", "title": "Continuation"}, {"id": "7c6673f5-264f-4ef7-86f8-e9ea9640eb86", "type": "concept", "title": "Cadential function"}, {"id": "3665dc1e-4688-4abe-a2d3-8f79e6647121", "type": "concept", "title": "Transition"}, {"id": "2322adbf-3b40-4901-b366-9d1608ecceac", "type": "concept", "title": "Retransition"}], "description": "Why learn it: Students learn to label passages by what they do, not only by where they sit."}]}, {"id": "cc44e728-8ff0-4acd-bc1c-99bedb079eea", "type": "topic", "title": "Binary and Ternary Forms", "description": "Binary and ternary forms train students to hear balance, contrast, return, and tonal planning. These forms also prepare students for larger Classical and Romantic structures.", "children": [{"id": "7f5fa20c-abe1-4892-9449-36dcfc613891", "type": "subtopic", "title": "Binary design", "children": [{"id": "894f0dcb-fd92-48c1-b3ed-9681e0951d62", "type": "concept", "title": "Simple binary"}, {"id": "69135ebf-311e-4294-bc5f-a0468cd385a3", "type": "concept", "title": "Rounded binary"}, {"id": "3fb446a4-04d4-47cf-9435-dc692daf81c1", "type": "concept", "title": "Balanced binary"}, {"id": "6db6ab6d-c973-4d43-bd29-f0f7f36f7b71", "type": "concept", "title": "Continuous vs. sectional"}, {"id": "cb0004e0-a8ad-485d-9af0-e20ce25f00f3", "type": "concept", "title": "Dance-suite contexts"}], "description": "Why learn it: Students distinguish repeated sections, tonal movement, and return procedures."}, {"id": "ab5cd672-dc9c-414a-ab15-8e069cb88508", "type": "subtopic", "title": "Ternary design", "children": [{"id": "e1a93d44-4262-4ef7-84f0-037ed20cca50", "type": "concept", "title": "Simple ternary"}, {"id": "d5f1efba-8d2b-41f6-a77a-81dedb2a84b7", "type": "concept", "title": "Compound ternary"}, {"id": "cccbfba1-d9d4-4778-a9a3-5dc7d63f6792", "type": "concept", "title": "Da capo form"}, {"id": "a24e5987-ece6-40e6-a302-99f336fc00e9", "type": "concept", "title": "Minuet and trio"}, {"id": "702efa94-4646-422e-b415-7d11e96b9ec8", "type": "concept", "title": "Scherzo and trio"}], "description": "Why learn it: Students learn how return creates memory, contrast, and proportion."}, {"id": "2b5a3d13-8f2b-4537-a038-28e3a8ed61bd", "type": "subtopic", "title": "Formal diagrams and listening", "children": [{"id": "ec1bb9d4-83b6-4f17-ba64-bc59d7a225eb", "type": "concept", "title": "Section labels"}, {"id": "266fbcbd-239a-4d37-9740-d348c1eafad4", "type": "concept", "title": "Key areas"}, {"id": "cddcfb83-1952-4c49-9742-c1298d1a10fa", "type": "concept", "title": "Repeat signs"}, {"id": "cdfef47b-f0ad-4acc-af99-d82e6b3a56f4", "type": "concept", "title": "Cadence locations"}, {"id": "84d0dd15-b627-486d-bfe4-7bbf7febfd77", "type": "concept", "title": "Listening timestamps"}], "description": "Why learn it: Students practice mapping form visually and aurally."}]}, {"id": "dd2860fa-474d-48b3-8eeb-230568063fea", "type": "topic", "title": "Theme and Variations", "description": "Variation form teaches students how composers preserve identity while changing surface, texture, harmony, meter, mode, or character. It is one of the clearest ways to study musical imagination.", "children": [{"id": "ac3b361b-7aad-4b8a-99ae-fbf960e06277", "type": "subtopic", "title": "Theme structure", "children": [{"id": "a5f11398-7d23-4907-a371-d7b966f4487b", "type": "concept", "title": "Phrase layout"}, {"id": "f1881619-fd9e-41c2-9e26-6711d9b24a50", "type": "concept", "title": "Bass line"}, {"id": "c2e782d3-9754-476d-a1d8-4b7889ef3ee1", "type": "concept", "title": "Harmonic skeleton"}, {"id": "d79df741-b27e-427d-9f18-207e0da907ea", "type": "concept", "title": "Cadences"}, {"id": "20e08c0b-44f0-4fce-9466-c25a3d9acf27", "type": "concept", "title": "Characteristic motives"}], "description": "Why learn it: Students learn to analyze the theme before discussing its variations."}, {"id": "73ee5b39-c3c9-4653-9188-0ce44d4d3abc", "type": "subtopic", "title": "Variation techniques", "children": [{"id": "5c424d95-4759-4cdf-ac94-d6a4b39acc19", "type": "concept", "title": "Figuration"}, {"id": "3a7ea9c2-2b6a-4228-a63c-1b9e56adb973", "type": "concept", "title": "Mode mixture"}, {"id": "f7ebbf50-f9fd-425d-a2e0-df9ce3f20f0b", "type": "concept", "title": "Meter change"}, {"id": "e37467be-b849-449c-87e2-1297b00be8dc", "type": "concept", "title": "Texture change"}, {"id": "5e71b2a6-1145-4a82-a9b8-ccd2b6113f20", "type": "concept", "title": "Rhythmic displacement"}], "description": "Why learn it: Students identify how each variation transforms the theme."}, {"id": "2adff90b-20e9-4387-8f70-822523da717d", "type": "subtopic", "title": "Large-scale variation cycles", "children": [{"id": "39df1e51-3179-4cae-9558-8e2abb595197", "type": "concept", "title": "Character sequence"}, {"id": "bac17b2e-13a0-4b8b-94a3-687afdafd06d", "type": "concept", "title": "Virtuosic escalation"}, {"id": "e5e96174-a7f9-4bd7-b488-2514b86254f0", "type": "concept", "title": "Slow variation"}, {"id": "649785fc-92d6-4bd3-b055-6ffa3a1a5b00", "type": "concept", "title": "Fugal variation"}, {"id": "23567a33-2136-4052-b74a-65a15e888b57", "type": "concept", "title": "Finale effect"}], "description": "Why learn it: Students learn how variation sets create drama over time."}]}, {"id": "04989d19-d139-4b09-9de4-a990a908445a", "type": "topic", "title": "Rondo Form", "description": "Rondo form helps students understand recurrence, contrast, tonal return, and episodic design. Students learn why the return of a refrain can feel stable, comic, heroic, or transformed.", "children": [{"id": "42825a20-a3ce-4c1e-a04d-cd44e65af7fc", "type": "subtopic", "title": "Rondo types", "children": [{"id": "37eeaca1-c4ed-40ed-8761-fb0024c6800e", "type": "concept", "title": "Five-part rondo"}, {"id": "0bc9e568-2c09-4bc5-b96b-bfa2371b0571", "type": "concept", "title": "Seven-part rondo"}, {"id": "1386d439-aadb-48d1-b367-3916e37db744", "type": "concept", "title": "Sonata rondo"}, {"id": "e5d843f3-3406-4eec-919c-cd375cdf7049", "type": "concept", "title": "Refrain variants"}, {"id": "efad191e-6c17-40f8-b1db-a54ee894333e", "type": "concept", "title": "Episode contrast"}], "description": "Why learn it: Students distinguish common refrain-and-episode patterns."}, {"id": "99a203be-9369-4eca-af37-dfa107ee556c", "type": "subtopic", "title": "Tonal and thematic planning", "children": [{"id": "bb432f81-cf55-484c-90af-a9bcdcf96b4b", "type": "concept", "title": "Home-key refrain"}, {"id": "d0e454ee-e336-4fd9-bc01-0144715f532e", "type": "concept", "title": "Contrasting episodes"}, {"id": "99c7e2f3-d15c-484f-a919-550f887f9be1", "type": "concept", "title": "Retransition"}, {"id": "2222f733-4161-410b-8724-93eddec3f42d", "type": "concept", "title": "Developmental episode"}, {"id": "8f5d6d3a-8cd2-4153-80c6-6ed4288ab915", "type": "concept", "title": "Coda"}], "description": "Why learn it: Students learn how rondos use key areas and returns to shape listener expectation."}, {"id": "5d9062e6-b264-4201-8465-9012f0b6fba5", "type": "subtopic", "title": "Style and genre contexts", "children": [{"id": "940ac721-2810-4f05-8b48-5ea23d476fcb", "type": "concept", "title": "Classical finales"}, {"id": "575762c1-9d63-42c8-bf7c-b4e6275c6235", "type": "concept", "title": "Concerto rondos"}, {"id": "99dcce9e-5e22-4cc7-bf98-758718bbd1e8", "type": "concept", "title": "Character pieces"}, {"id": "cc31c0c5-83f0-4188-a79e-f814e5d0a5f9", "type": "concept", "title": "Virtuosity"}, {"id": "a3a5a843-acc8-4dbb-b2a8-b49cef31f5ee", "type": "concept", "title": "Humor and closure"}], "description": "Why learn it: Students place rondo in sonatas, concertos, chamber music, and finales."}]}, {"id": "152cd709-e737-4a7c-9959-6a07be6d843b", "type": "topic", "title": "Sonata Form", "description": "Sonata form is a central topic in advanced analysis because it joins theme, harmony, rhetoric, development, return, and historical convention. Students learn both standard models and flexible analytical approaches.", "children": [{"id": "178691f3-7aa5-43e2-877b-9bd819a26fe3", "type": "subtopic", "title": "Exposition functions", "children": [{"id": "9086019c-0910-441b-84d1-437b98039c73", "type": "concept", "title": "Primary theme"}, {"id": "960d969b-1cb8-4de0-bf0a-a05f999ede05", "type": "concept", "title": "Transition"}, {"id": "d756b652-e6da-4797-9f81-9c4bee71c909", "type": "concept", "title": "Medial caesura"}, {"id": "69268550-a8be-4797-be76-7d04bc86b352", "type": "concept", "title": "Secondary theme"}, {"id": "7040f46e-f5ec-41aa-81a0-4f4145f08a11", "type": "concept", "title": "Closing zone"}], "description": "Why learn it: Students learn how primary, transition, secondary, and closing materials create tonal and thematic contrast."}, {"id": "c8f5f7c4-6414-4d01-8378-bcdf63110f6b", "type": "subtopic", "title": "Development and recapitulation", "children": [{"id": "7aaa97de-7f2c-4113-b74a-ae28db6e3b5a", "type": "concept", "title": "Developmental core"}, {"id": "be09cb4c-6d81-4449-807e-0fb6facc02b4", "type": "concept", "title": "Retransition"}, {"id": "68237c59-5b05-40fa-bb88-98df663cb557", "type": "concept", "title": "Recapitulatory adjustment"}, {"id": "82f29f5b-5e75-42a0-bdb2-b7d50233134e", "type": "concept", "title": "Tonal resolution"}, {"id": "3090d817-7f32-4bf9-94a9-5f4ab5f7cd45", "type": "concept", "title": "Coda"}], "description": "Why learn it: Students study how instability, fragmentation, sequence, and return create formal drama."}, {"id": "c168ab6b-1843-4adc-9da2-c658bad340ed", "type": "subtopic", "title": "Sonata-theory perspectives", "children": [{"id": "0b2e82e6-f579-4c76-960a-6fd9e727ae38", "type": "concept", "title": "Rotational form"}, {"id": "8d8f359a-87e8-4c77-8bb8-9b681fe02ad4", "type": "concept", "title": "Essential expositional closure"}, {"id": "18858804-c639-4e42-8ec2-72a22f19b9c1", "type": "concept", "title": "Deformation"}, {"id": "e7fb766b-2a04-4263-9575-af268dea17e1", "type": "concept", "title": "Default options"}, {"id": "3f58c537-c7af-44fe-9eac-0a43e9c29a63", "type": "concept", "title": "Historical norms"}], "description": "Why learn it: Students gain vocabulary for more refined sonata analysis without treating one model as mechanical law."}]}, {"id": "ab5c2176-beda-4591-8c0b-e2213f4826db", "type": "topic", "title": "Concerto Form", "description": "Concerto form adds public display, dialogue, ritornello logic, orchestral framing, and soloistic drama to sonata thinking. Students learn to analyze the relationship between individual and ensemble.", "children": [{"id": "2af42c64-127f-418d-8bd6-99343c43baca", "type": "subtopic", "title": "Ritornello and solo design", "children": [{"id": "b77f348a-a15f-409c-aa00-6cf31db029b3", "type": "concept", "title": "Opening ritornello"}, {"id": "94ed8452-895d-4e87-9ab8-de99d91ff159", "type": "concept", "title": "Solo exposition"}, {"id": "ffc6fd42-7eaa-4498-ac4a-1ebd7cbbb65e", "type": "concept", "title": "Tutti returns"}, {"id": "c67c84a1-d370-465e-9476-e84f0efb118c", "type": "concept", "title": "Episode design"}, {"id": "74622e0e-3a92-400d-80d7-d5aced984a42", "type": "concept", "title": "Recapitulation"}], "description": "Why learn it: Students identify how orchestral returns and solo episodes shape structure."}, {"id": "4fcaca85-871f-4b4d-9f09-de480967654a", "type": "subtopic", "title": "Virtuosity and rhetoric", "children": [{"id": "eec25612-161b-48da-b018-e7b6d5cd3cc5", "type": "concept", "title": "Cadenza"}, {"id": "0bf1ff1e-70f6-450a-81ee-517fb7f98675", "type": "concept", "title": "Solo entrance"}, {"id": "25b452d1-c0cf-4f84-887a-8addff26fa83", "type": "concept", "title": "Bravura passagework"}, {"id": "db1eafb0-d09f-46d4-97c9-1a9a6a32f476", "type": "concept", "title": "Dialogue"}, {"id": "17fe5757-834e-460a-96fe-5b55cc567088", "type": "concept", "title": "Orchestral response"}], "description": "Why learn it: Students learn how display, risk, and persona become formal forces."}, {"id": "e140603c-d6be-4fc6-8b7f-beba3ad1113f", "type": "subtopic", "title": "Historical concerto models", "children": [{"id": "69273089-c227-4f2f-908d-86d0e8f8eb7c", "type": "concept", "title": "Vivaldi model"}, {"id": "be096b07-becf-4fe3-b883-3d42e266509d", "type": "concept", "title": "Mozart concerto"}, {"id": "fe74f6d1-890a-4e37-a8d3-5f75692b0d81", "type": "concept", "title": "Romantic expansion"}, {"id": "abdeefe0-124f-41ab-9673-c6d0adbbb1e9", "type": "concept", "title": "20th-century concerto"}, {"id": "9d537746-2f7c-49b6-b837-05df83637ce5", "type": "concept", "title": "Concerto grosso references"}], "description": "Why learn it: Students compare Baroque, Classical, Romantic, and modern concerto strategies."}]}, {"id": "c88121ae-52e3-450a-bf1c-51faa5e69252", "type": "topic", "title": "Fugue and Contrapuntal Forms", "description": "Fugue teaches students how form can emerge from contrapuntal process rather than sectional blocks alone. Students learn to follow subject, answer, countersubject, episodes, stretto, and tonal design.", "children": [{"id": "490beeb7-45f5-4fae-8dd0-0a2f4460fdc8", "type": "subtopic", "title": "Exposition and entries", "children": [{"id": "fc65d258-f675-48d2-af1c-d0be174c8297", "type": "concept", "title": "Subject"}, {"id": "0128ba6a-7d60-4372-b865-af2c14708f52", "type": "concept", "title": "Answer"}, {"id": "2b5fc2e6-aa15-430d-926f-4e4309c4da77", "type": "concept", "title": "Countersubject"}, {"id": "484d1b65-18d9-493f-8280-1850e9745bf7", "type": "concept", "title": "Real vs. tonal answer"}, {"id": "67e33f69-1927-424b-916f-477a9eac4f4f", "type": "concept", "title": "Order of voices"}], "description": "Why learn it: Students learn the basic grammar of fugal openings."}, {"id": "c154a9a7-3f3d-468a-ad12-d0ba9a7c2355", "type": "subtopic", "title": "Episodes and development", "children": [{"id": "49d04db9-4034-4383-92f0-5385aa270a03", "type": "concept", "title": "Sequence"}, {"id": "81bd320e-fd9a-4f53-bf8e-590c7e058509", "type": "concept", "title": "Invertible counterpoint"}, {"id": "41bfa394-926c-4781-8105-c1b91fa1120c", "type": "concept", "title": "Fragmentation"}, {"id": "7fa4654f-2a7c-4524-8bd9-83e28bb289bc", "type": "concept", "title": "Stretto"}, {"id": "b5581754-6c18-4964-8fc5-df911faefc7d", "type": "concept", "title": "Pedal point"}], "description": "Why learn it: Students trace how fugues generate motion between subject entries."}, {"id": "cf1e07b8-f0ba-41be-9dff-31e336f13082", "type": "subtopic", "title": "Contrapuntal genres", "children": [{"id": "91cc4c92-67e3-44c0-ab95-8e5b181468c1", "type": "concept", "title": "Canon"}, {"id": "1a851eb4-2c77-4560-bf9e-b416f165be40", "type": "concept", "title": "Invention"}, {"id": "3dfa8463-fbda-4c52-a6c9-b6f6da616ec4", "type": "concept", "title": "Fugato"}, {"id": "d976228e-c55d-495c-bfc7-589d5f257a5c", "type": "concept", "title": "Passacaglia"}, {"id": "5ae6d063-5c0e-4aa0-8be3-44b2454bfe03", "type": "concept", "title": "Chaconne"}], "description": "Why learn it: Students compare fugue with related imitative and learned-style forms."}]}, {"id": "8813ce38-aab5-4d8a-92dc-7f9837564a79", "type": "topic", "title": "Large-Scale Forms", "description": "Large-scale forms train students to think across entire movements, cycles, and works. The goal is to connect local details to long-range design, dramatic pacing, and genre expectations.", "children": [{"id": "b30e1207-aea4-4b38-90d6-9e20c5b51502", "type": "subtopic", "title": "Multi-movement cycles", "children": [{"id": "45318902-c314-4e2b-9b8b-39bb0130c103", "type": "concept", "title": "Cycle planning"}, {"id": "f9e4a9de-afbc-41a3-bf3a-8d1acb60ad95", "type": "concept", "title": "Key relationships"}, {"id": "2f87ba1c-7468-40d4-9497-a6fad2b2cc09", "type": "concept", "title": "Tempo sequence"}, {"id": "fbc029ab-f51e-46c2-b63a-d44fdd7ac8ba", "type": "concept", "title": "Thematic recall"}, {"id": "c852daed-93f2-456b-8b7c-777674a4cddf", "type": "concept", "title": "Finale function"}], "description": "Why learn it: Students study how movements relate within sonatas, symphonies, quartets, and suites."}, {"id": "4b663d02-49fb-4347-b729-0bd302b245a5", "type": "subtopic", "title": "Through-composed and sectional designs", "children": [{"id": "4f0d583d-1936-4780-b516-473942eb85b1", "type": "concept", "title": "Through-composed song"}, {"id": "7cef6805-53dc-4758-81cb-d199f4ce31a8", "type": "concept", "title": "Strophic form"}, {"id": "125e8038-fe73-41c1-bfa9-098a4628a9e1", "type": "concept", "title": "Arch form"}, {"id": "1fb28107-4075-47b4-bd5f-8614715a678a", "type": "concept", "title": "Cyclic form"}, {"id": "3232c0ea-ce24-4c54-909f-5e3e58cf90b9", "type": "concept", "title": "Medley and suite logic"}], "description": "Why learn it: Students distinguish forms that develop continuously from forms built from clear returns or sections."}, {"id": "7f9652a2-e7bf-4e75-bb09-92948f5976c0", "type": "subtopic", "title": "Large-scale narrative", "children": [{"id": "51f54c62-e285-4852-88bb-3e97901c1ebc", "type": "concept", "title": "Tonal journey"}, {"id": "5051168c-5f50-40d3-b6cb-e17e822de42c", "type": "concept", "title": "Thematic transformation"}, {"id": "03063787-45f8-4a81-a2ac-a9909fcbba5a", "type": "concept", "title": "Climactic design"}, {"id": "a5cfaae8-cf9c-492a-b857-78b4e011850d", "type": "concept", "title": "Text-music relation"}, {"id": "496c90cc-59a5-479b-99f6-96f173dab2c5", "type": "concept", "title": "Ending strategy"}], "description": "Why learn it: Students learn to describe dramatic or expressive arcs without replacing evidence with vague storytelling."}]}, {"id": "61f56434-3833-404c-af22-aa4daae341c9", "type": "topic", "title": "20th-Century and Contemporary Forms", "description": "Modern and contemporary music often requires expanded analytical tools. Students learn how form can be shaped by collections, timbre, rhythm, process, technology, text, improvisation, or concept.", "children": [{"id": "6efd8373-e2c9-4482-9bee-a8f78022bc8f", "type": "subtopic", "title": "Post-tonal form", "children": [{"id": "75cbc566-2067-4304-b508-1a0940c19a6f", "type": "concept", "title": "Set-class identity"}, {"id": "6b15d7a0-f25f-46ab-8eb4-63f1efeddb05", "type": "concept", "title": "Serial rows"}, {"id": "abb9c0b7-e717-4bc2-b261-f11fdafcf558", "type": "concept", "title": "Centricity"}, {"id": "ff2ff060-d966-4e4e-b645-d757348b59ef", "type": "concept", "title": "Collections"}, {"id": "2ac2bd0d-591f-442c-aa29-97a845bda681", "type": "concept", "title": "Transformation networks"}], "description": "Why learn it: Students analyze structures built from pitch-class sets, rows, collections, or interval cycles."}, {"id": "d252068e-39a0-4aa2-828d-f3453f64e3cb", "type": "subtopic", "title": "Rhythmic, metric, and timbral form", "children": [{"id": "6158739b-a683-4663-9bd1-48276f609e1d", "type": "concept", "title": "Additive process"}, {"id": "2c48883b-e8b4-4b58-aec3-6dc479143b59", "type": "concept", "title": "Metric modulation"}, {"id": "dc5975da-4f2e-406a-9b7f-fb5a3c56afa8", "type": "concept", "title": "Timbre blocks"}, {"id": "d0ed8182-a649-4daf-b452-43bc4f55d6b4", "type": "concept", "title": "Texture fields"}, {"id": "ff32f1dd-8229-4f5f-b82b-e49da6680d7c", "type": "concept", "title": "Minimalist process"}], "description": "Why learn it: Students learn to analyze form where rhythm, texture, sound color, or process leads the structure."}, {"id": "97ae27ce-5163-45b8-b481-c8c1d433cf71", "type": "subtopic", "title": "Popular, jazz, and multimedia forms", "children": [{"id": "8b5a2884-ff9e-4f7d-8e1f-25c7408c769d", "type": "concept", "title": "Song forms"}, {"id": "8eb13e02-c1f7-4e86-b68f-6ed4a69bb0f6", "type": "concept", "title": "12-bar blues"}, {"id": "e7ec5916-908e-4cc5-88db-833b4489df9a", "type": "concept", "title": "Head-solo-head"}, {"id": "ff0e0202-7313-461a-8ed7-954a377a7c94", "type": "concept", "title": "Loop-based form"}, {"id": "165bd430-209d-4789-84e5-90573d41e998", "type": "concept", "title": "Film/game music cues"}], "description": "Why learn it: Students broaden formal analysis beyond the common-practice canon."}]}, {"id": "14433d0e-8a33-4085-860e-faab0d57005d", "type": "topic", "title": "Comparative, Corpus, and Listening-Based Analysis", "description": "This added topic makes analysis more rigorous and contemporary. Students compare multiple works, use listening evidence, and learn how larger datasets or style corpora can support analytical claims.", "children": [{"id": "a33559ea-ddef-42f0-be55-298ac918d185", "type": "subtopic", "title": "Comparative analysis", "children": [{"id": "56cb454b-8f6b-42c4-bc74-89cf182c75c8", "type": "concept", "title": "Same-form comparison"}, {"id": "a2dc7a83-19fb-4d67-977d-41b45c2acaf7", "type": "concept", "title": "Composer style"}, {"id": "890423b8-7f6d-4b84-9e49-6695c73b1d7b", "type": "concept", "title": "Genre conventions"}, {"id": "ea420cc6-d0b1-4715-a931-8250fd218320", "type": "concept", "title": "Historical change"}, {"id": "98667bed-e359-4619-a2c0-b362ec3ebea2", "type": "concept", "title": "Performance variants"}], "description": "Why learn it: Students learn to compare pieces without flattening stylistic or historical difference."}, {"id": "ebed3080-30f9-4619-b0b3-88106bf8a292", "type": "subtopic", "title": "Listening as evidence", "children": [{"id": "1c24f9a9-fdb8-4383-b759-279df20c71aa", "type": "concept", "title": "Timestamps"}, {"id": "05df1897-15b2-42e9-9561-053b43fe1010", "type": "concept", "title": "Formal hearing"}, {"id": "2b549a30-3909-44d4-a967-158cc33516a7", "type": "concept", "title": "Performance tempo"}, {"id": "ee8fba62-c603-4001-82b9-c533dd9b3b14", "type": "concept", "title": "Recording comparison"}, {"id": "e5011cf3-aa06-49a4-92ef-610eb4263de6", "type": "concept", "title": "Aural ambiguity"}], "description": "Why learn it: Students connect score analysis to the sounding experience."}, {"id": "b1121417-d4d6-4e0a-a966-1cf461765096", "type": "subtopic", "title": "Introductory corpus thinking", "children": [{"id": "ab2bf560-83cd-4ead-9d42-668436edc448", "type": "concept", "title": "Norms and outliers"}, {"id": "e0b81249-bdf0-49e8-8973-fd5f16ab4033", "type": "concept", "title": "Spreadsheet coding"}, {"id": "29285430-8f80-4d4a-9783-15897836c073", "type": "concept", "title": "Theme-type counts"}, {"id": "e9247755-d056-4c2a-8898-e6ef417b5a06", "type": "concept", "title": "Key schemes"}, {"id": "1b845bc0-5d67-40a5-95cb-02d3ce8ffe11", "type": "concept", "title": "Citation of datasets"}], "description": "Why learn it: Students learn how patterns across many works can clarify norms and exceptions."}]}, {"id": "17734ae8-091f-48cb-800a-ad2f2d54aa0d", "type": "topic", "title": "Analytical Writing", "description": "Analysis becomes valuable when students can make a clear, evidence-based musical argument. This section trains students to move from labels to claims, from observations to interpretation, and from diagrams to prose.", "children": [{"id": "0cc23acb-276c-4802-bd81-6e67a55abd42", "type": "subtopic", "title": "Analytical claims", "children": [{"id": "27ec6aac-275d-47f1-9370-debd905b3baa", "type": "concept", "title": "Thesis statements"}, {"id": "9c709112-27f2-4d57-8d0b-fd762a34a254", "type": "concept", "title": "Musical evidence"}, {"id": "87338b86-35ac-4b0a-a783-8fa72841c320", "type": "concept", "title": "So-what reasoning"}, {"id": "e1ade8af-2b64-413f-bd5e-7e029f668e95", "type": "concept", "title": "Scope control"}, {"id": "d1566fb0-3c33-4911-bcd3-c658eef341ab", "type": "concept", "title": "Terminology precision"}], "description": "Why learn it: Students learn to write arguments that explain why a formal feature matters."}, {"id": "719199ef-39a8-4288-8a03-d95cade61b69", "type": "subtopic", "title": "Examples, diagrams, and citations", "children": [{"id": "19fb5564-4e31-4ad1-8fb4-7c01f311962e", "type": "concept", "title": "Annotated score examples"}, {"id": "7e5dd25a-8d52-4c74-9951-d720983d7efc", "type": "concept", "title": "Formal diagrams"}, {"id": "5d36754d-9003-41c9-882c-e4de84896f4c", "type": "concept", "title": "Measure-number references"}, {"id": "0c3d1fec-7504-4ab6-a92c-3091317ae52f", "type": "concept", "title": "Source citation"}, {"id": "95e444f8-4ecf-4b15-87d2-01f930d620b8", "type": "concept", "title": "Copyright-aware excerpts"}], "description": "Why learn it: Students learn to present analytical work clearly and ethically."}, {"id": "d2595565-2c91-48a7-b972-aa92cc9dfe0b", "type": "subtopic", "title": "Revision and peer review", "children": [{"id": "b6a9cf1f-94a9-4b45-96d3-271422603921", "type": "concept", "title": "Reverse outlining"}, {"id": "ac8f947f-0ade-423a-924c-d207d9738908", "type": "concept", "title": "Peer critique"}, {"id": "3c397eef-5b05-4df6-9cc4-251f277cba69", "type": "concept", "title": "Evidence checks"}, {"id": "015ed8e9-1cef-40b0-be50-3a5fb4a2c372", "type": "concept", "title": "Clarity edits"}, {"id": "2311440f-7103-4775-8a5c-64d6364be324", "type": "concept", "title": "Final polish"}], "description": "Why learn it: Students practice improving analytical prose through feedback."}]}], "dbBacked": true}$fanajson$::jsonb,
